// The one card-reference table (CARD_FIELDS, generated by scripts/gen-contract.mjs from the event and
// write item schemas): every ledger event type and write item type has a row, and no row lacks one;
// every field an event schema marks as naming a card (a `$ref` to nodeNumber or nodeRef, or a list of
// them) is in its type's row, found here by a plain scan of the files rather than the generator's own
// walk; and the table as it stands, so a new card field is seen in review.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { SCHEMA_DIR } from '../src/files.ts';
import { CARD_FIELDS, cardFields } from '../src/index.ts';

type Rec = Record<string, any>;
const read = (rel: string): Rec => JSON.parse(fs.readFileSync(path.join(SCHEMA_DIR, rel), 'utf8'));
const CARD_REF = /#\/\$defs\/(nodeNumber|nodeRef|nodeNumbers|cards)$/;

/** Each event type, from ledger-event.schema.json's branches: its file and its `type` const. */
function eventTypes(): { file: string; type: string }[] {
  return (read('ledger-event.schema.json').oneOf as Rec[]).map((b) => {
    const file = /events\/([a-z-]+\.schema\.json)#/.exec(String(b.$ref))![1]!;
    const stored = read(`events/${file}`).$defs.stored;
    const own = [stored, ...(stored.allOf ?? [])].find((p: Rec) => p.properties?.type?.const);
    return { file, type: String(own.properties.type.const) };
  });
}

/** Every property name in a schema file whose schema is a card reference, outside `examples`. */
function cardNames(node: unknown, out = new Set<string>()): Set<string> {
  if (Array.isArray(node)) node.forEach((x) => cardNames(x, out));
  else if (node && typeof node === 'object') {
    for (const [k, v] of Object.entries(node as Rec)) {
      if (k === 'examples') continue;
      if (k === 'properties') for (const [name, p] of Object.entries(v as Rec)) if (CARD_REF.test(String(p?.$ref ?? p?.items?.$ref ?? ''))) out.add(name);
      cardNames(v, out);
    }
  }
  return out;
}

/** Each write item type, from write-item.schema.json's forms. */
const itemTypes = (): string[] => (read('api/write-item.schema.json').oneOf as Rec[]).map((b) => {
  if (!b.$ref) return String(b.properties.type.const);
  const [file, pointer] = String(b.$ref).split('#');
  const form = read(`events/${/events\/(.+)$/.exec(file!)![1]}`).$defs[pointer!.split('/').at(-1)!];
  return String([form, ...(form.allOf ?? [])].find((p: Rec) => p.properties?.type?.const).properties.type.const);
});

test('every ledger event type and write item type has a row, and no row lacks a type', () => {
  assert.deepEqual(Object.keys(CARD_FIELDS).sort(), [...new Set([...eventTypes().map((e) => e.type), ...itemTypes()])].sort());
});

test('every field an event schema marks as naming a card is in its row', () => {
  for (const { file, type } of eventTypes()) {
    const fields = new Set(cardFields(type).map((f) => f.field));
    for (const name of cardNames(read(`events/${file}`))) assert.ok(fields.has(name), `${type}: ${name} names a card but is not in CARD_FIELDS`);
  }
});

test('the table as it stands; an unknown type has no card fields', () => {
  assert.deepEqual(CARD_FIELDS, {
    board: [], region: [{ field: 'center', in: 'region' }], node: [{ field: 'n' }],
    link: [{ field: 'from' }, { field: 'to' }], unlink: [{ field: 'from' }, { field: 'to' }],
    act: [{ field: 'n' }, { field: 'nodes', list: true }], seen: [{ field: 'n' }], reply: [{ field: 'n' }],
    propose: [{ field: 'n' }], park: [{ field: 'n' }], join: [], 'grant-request': [],
    retire: [{ field: 'cards', list: true }, { field: 'n' }], append: [{ field: 'n' }],
  });
  assert.deepEqual([cardFields('nope'), cardFields('constructor'), cardFields(undefined)], [[], [], []]);
});
